/**
 * เขตเวลาที่ใช้อ้างอิงจุดเริ่มต้นสัปดาห์ (REQ-15)
 *
 * REQUIREMENTS.md ไม่ได้ระบุเขตเวลาของ "00:00" ไว้ — สมมติ Asia/Bangkok (+07:00) คงที่
 * ตามตัวอย่างค่า offset ใน REQ-50 และเพราะระบบให้บริการศูนย์คอมพิวเตอร์ในไทย
 * ใช้ offset คงที่ (ไม่คำนวณจาก timezone ของเครื่องที่รันโค้ด) เพื่อให้ผลลัพธ์คงที่ไม่ว่าจะรันที่ไหน
 */
const WEEK_TZ_OFFSET_MINUTES = 7 * 60;

/**
 * จุดเริ่มต้นของสัปดาห์ (วันจันทร์ 00:00 เวลาไทย) ที่เวลาที่ให้มาตกอยู่ (REQ-15)
 *
 * ใช้เป็น "กุญแจ" จัดกลุ่มการจองรายสัปดาห์สำหรับนับโควตา (REQ-14) — สองเวลาที่อยู่สัปดาห์เดียวกัน
 * จะได้ผลลัพธ์เดียวกัน
 */
export function weekStartIso(dateIso: string): string {
  const local = new Date(new Date(dateIso).getTime() + WEEK_TZ_OFFSET_MINUTES * 60000);
  const daysSinceMonday = (local.getUTCDay() + 6) % 7;
  local.setUTCHours(0, 0, 0, 0);
  local.setUTCDate(local.getUTCDate() - daysSinceMonday);
  return new Date(local.getTime() - WEEK_TZ_OFFSET_MINUTES * 60000).toISOString();
}

